import React from 'react';
import {
  Briefcase,
  Eye,
  GraduationCap,
  HeartPulse,
  Leaf,
  Scale,
  ShieldCheck,
  TrendingUp,
} from 'lucide-react';

// ─── Types ────────────────────────────────────────────────────────────────────

export interface Official {
  name: string;
  title: string;
  party?: string;
  since?: string;
  photoUrl?: string;
  // Affidavit data (ECI self-declared, sourced from ADR/myneta.info)
  criminalCases?: number;          // declared pending cases
  criminalCaseNote?: string;       // brief description if > 0
  education?: string;              // highest qualification (verbatim from affidavit)
  educationScore?: number;         // 0–100: PhD=100, PG=85, GradProf=82, Grad=75, 12th=55, 10th=40, 8th=25
  /** Serious IPC charges (≥5yr / hate-speech / financial fraud per ADR definition). Defaults to 0. */
  seriousCriminalCases?: number;
  affidavitYear?: number;
}

export interface OfficialGroup {
  group: string;
  officials: Official[];
}

export interface IndicatorStat {
  label: string;
  value: string;
  note?: string;
  noteHi?: string;          // Hindi translation of note
  source: string;
}

export interface Indicator {
  key: string;
  label: string;
  score: number; // 0–100
  icon: React.ElementType;
  headline: string;
  headlineHi?: string;      // Hindi translation of headline
  stats: IndicatorStat[];
}

export interface CagFinding {
  scheme: string;
  schemeSlug: string;       // links to /schemes/:slug
  reportRef: string;
  reportYear: number;
  severity: 'critical' | 'major' | 'minor';
  parameter: string;        // audit parameter / aspect under scrutiny
  finding: string;          // CAG summary finding
  findingHi?: string;       // Hindi translation of finding
  actual?: string;          // what audit found on the ground
  reportExcerpt?: string;   // verbatim excerpt from CAG report
  reportExcerptHi?: string; // Hindi translation of reportExcerpt
  sourceUrl: string;        // direct link to CAG PDF / page
}

export interface AccountabilityRating {
  key: string;
  label: string;
  score: number;            // 0–100
  icon: React.ElementType;
  methodology: string;      // brief plain-language note
}

export interface NewGovtCabinetMember {
  name: string;
  party: string;
  portfolio: string;
  criminalCases?: number;
  seriousCriminalCases?: number;
  education?: string;
  educationScore?: number;
}

export interface NewGovtDetails {
  cm: {
    name: string;
    party: string;
    since: string;
    note?: string;
    criminalCases: number;
    criminalCaseNote?: string;
    seriousCriminalCases?: number;
    education: string;
    educationScore: number;
  };
  cabinet: NewGovtCabinetMember[];
}

export type StatePromiseStatus = 'implemented' | 'partial' | 'in-progress' | 'not-fulfilled' | 'pending';

export interface StateManifestoPromise {
  promise: string;
  promiseHi: string;
  status: StatePromiseStatus;
  note: string;
  noteHi: string;
  cagVerdict?: string;
  cagVerdictHi?: string;
  cagSource?: string;
  /** CAG-flagged rupee amount in crore (funds lapsed / wasted / misappropriated) */
  cagAmountCrore?: number;
}
export interface StateManifestoCategory {
  name: string;
  nameHi: string;
  promises: StateManifestoPromise[];
}
export interface StateManifesto {
  year: number;
  party: string;      // e.g. 'BJP', 'Congress', 'AAP', 'TMC', 'JMM'
  partyHi: string;    // e.g. 'भाजपा', 'कांग्रेस', 'आप', 'तृणमूल'
  title: string;
  titleHi: string;
  tagline: string;
  taglineHi: string;
  sourceUrl: string;
  categories: StateManifestoCategory[];
}

export interface StateFact {
  stateCode: string;
  name: string;
  capital: string;
  region: string;
  cm: Official;
  officialGroups: OfficialGroup[];
  cagFindings: CagFinding[];
  accountabilityRatings: AccountabilityRating[];
  indicators: Indicator[];
  newGovtYear?: number;
  newGovtLabel?: string;
  newGovtDetails?: NewGovtDetails;
  manifestos?: StateManifesto[];
}

